/**
 * REBOUND — shared contract.
 *
 * This file is the single source of truth between three workstreams:
 *   - src/model.ts    pure simulation core (implements ModelApi, no DOM)
 *   - src/content.ts  data for eras, applications, upgrades, levers… (exports `content: Content`)
 *   - src/ui/*        DOM interface (reads Derived, calls ModelApi)
 *
 * Do not edit this file from a workstream. If the contract is wrong or missing something,
 * work around it locally and report it in your final message.
 *
 * Conventions
 *   - All rates are per real second of play. `dt` is in seconds.
 *   - ModelApi functions are PURE: never mutate the state passed in, always return a new state.
 *     No Date.now(), no Math.random() (use state.seed with a small deterministic PRNG if needed).
 *   - Money is "£" in every era for simplicity.
 */

export type EraId = 'steam' | 'light' | 'motion' | 'compute' | 'code';

export const ERA_ORDER: EraId[] = ['steam', 'light', 'motion', 'compute', 'code'];

/** In-game years that pass per real second (3 years a minute). Cosmetic clock + Steady State timer. */
export const YEARS_PER_SECOND = 0.05;
/** In-game years of continuous decoupling needed for Steady State. */
export const STEADY_STATE_YEARS = 50;
export const START_YEAR = 1780;
export const SAVE_VERSION = 1;

/* ------------------------------------------------------------------ */
/* CONTENT (static data, never changes during play)                    */
/* ------------------------------------------------------------------ */

export interface Content {
  eras: Record<EraId, EraDef>;
  upgrades: UpgradeDef[];
  levers: LeverDef[];
  knowhow: KnowhowDef[];
  institutions: InstitutionDef[];
  achievements: AchievementDef[];
  /** Broadsheet headline variants keyed by event. `{era}`, `{app}`, `{resource}`, `{service}` are substituted by the model. */
  headlines: Record<HeadlineKey, string[]>;
  global: GlobalParams;
}

export interface GlobalParams {
  /** Starting capital of a fresh run. */
  startCapital: number;
  /** Seconds of current income granted per manual click (the "sell power by hand" button). */
  clickSeconds: number;
  /** Flat capital per click so the very first click does something. */
  clickFlat: number;
  /** Population growth per second per point of wellbeing above subsistence. Population starts at 1. */
  popGrowth: number;
  /** Wellbeing (0–100 scale) below which population does not grow. */
  subsistence: number;
  /** Wellbeing the player must hold for Steady State. */
  wellbeingTarget: number;
  /** Mandate per second per point of wellbeing above `mandateFloor`. */
  mandateRate: number;
  mandateFloor: number;
  /** Mandate granted by each Pressure crisis (the political window). */
  crisisMandate: number;
  /** Fraction of population lost in each Pressure crisis. */
  crisisPopLoss: number;
  /** Hindsight formula weights: see ModelApi.hindsightOnReckon. */
  hindsight: { perPeakWellbeing: number; perDecoupledYear: number; perEraReached: number; perSteadyEra: number };
  /** Offline progress cap in seconds. */
  offlineCapSeconds: number;
}

export interface EraDef {
  id: EraId;
  /** 1–5 */
  index: number;
  name: string;            // "Steam"
  years: string;           // "1780–1870"
  tagline: string;         // one line shown when the era opens
  service: { name: string; unit: string };    // "Motive power", "hp"
  resource: { name: string; unit: string };   // "Coal", "tons"
  pressure: { name: string; crisisName: string }; // "Smog", "The Great Stink"
  /** CSS theme key the UI switches on. */
  theme: 'ledger' | 'gaslight' | 'chrome' | 'terminal' | 'agentic';

  /* --- price side --- */
  /** p_0: base resource price. */
  basePrice: number;
  /** c: capital + labour cost per unit of service (before upgrades). */
  capCost: number;
  /** m: the player's cut of spending on the service. */
  margin: number;
  /** Starting efficiency η (service per unit resource). Usually 1. */
  baseEta: number;
  /**
   * Era 4 twist. If > 0, η grows on its own by this exponential rate per second once the era is open
   * (η *= exp(autoEtaRate * dt)). The player cannot switch it off.
   */
  autoEtaRate: number;

  /* --- resource side --- */
  /**
   * 'stock': a depletable reserve Q. p_r = basePrice * (Q0 / Q)^alpha. Run ends if Q hits 0.
   * 'flow' : a renewable capacity per second (Era 5 attention). p_r = basePrice * (1 / (1 - u))^alpha
   *          where u = min(0.98, R / effectiveCapacity). Never runs out; just gets scarce.
   */
  resourceKind: 'stock' | 'flow';
  /** Q0 for 'stock'; capacity per second for 'flow'. Both scale with nothing unless effects say so. */
  reserve: number;
  alpha: number;

  /* --- pressure side --- */
  /**
   * 'resource': P += R * pressureIntensity * dt  (smog, carbon)
   * 'service' : P += D * pressureIntensity * dt  (Era 5: every shipped feature adds to the code stock)
   */
  pressureSource: 'resource' | 'service';
  pressureIntensity: number;
  /** Fraction of P absorbed per second. 0 for Era 5 (code never rots away on its own). */
  absorption: number;
  /** P at which the run collapses (forced Reckoning). */
  collapseAt: number;
  /** Crisis events fire the first time P crosses each of these fractions of collapseAt, e.g. [0.4, 0.7]. */
  crisisAt: number[];
  /** Wellbeing points lost at P = collapseAt (scaled linearly below that). */
  pressureWellbeingCost: number;
  /**
   * Era 5 twist. Capacity eaten per unit of P per second (maintenance upkeep on the code stock).
   * effectiveCapacity = max(5% of reserve, reserve - P * pressureUpkeep). 0 elsewhere.
   */
  pressureUpkeep: number;

  /* --- wellbeing --- */
  /** Weight of this service in wellbeing: W_e = wellbeingWeight * ln(1 + D / (N * wellbeingScale)). */
  wellbeingWeight: number;
  wellbeingScale: number;

  /* --- cross-era links --- */
  /**
   * Indirect rebound (Era 2+). Money households save on this service is spent on an earlier one.
   * Saturation of every application in `spill.to` is multiplied by
   *   1 + spill.rate * max(0, 1 - p_s / p_s_at_era_open)
   * (reduced by 'greenSpending' levers).
   */
  spill?: { to: EraId; rate: number };
  /** Era 5 → Era 4. Each unit of this era's service adds this much service demand to `drawsOn.era`. */
  drawsOn?: { era: EraId; perService: number };

  /* --- unlock --- */
  /** Era 1 has no unlock. Others open automatically once both conditions hold. */
  unlock?: { prevServicePriceBelow: number; minReckonings: number };

  applications: ApplicationDef[];
}

export interface ApplicationDef {
  id: string;              // unique across the whole game, e.g. 'steam.mills'
  name: string;            // "Cotton mills"
  blurb: string;           // one line of flavour
  /** Small pictogram the UI draws (the UI owns a set of inline SVGs keyed by this). */
  icon: string;
  /** p_i: service price at which half of saturation is adopted. */
  halfPrice: number;
  /** S_i: demand at full saturation for population 1. */
  saturation: number;
  /** k_i: steepness (elasticity while the use is young). */
  steepness: number;
  /**
   * Frontier rebound. The application becomes *available* the first time p_s <= visibleBelow
   * (Infinity = from the start). The player then pays `foundCost` capital to found it.
   * Demand is zero until founded. foundCost 0 = founded automatically when available.
   */
  visibleBelow: number;
  foundCost: number;
  /** Era 1 twist: each unit of this application's demand adds this much to the reserve per second. */
  reserveGainPerService?: number;
  /** Era 3 twist: demand never falls below this fraction of the application's own peak (lock-in). 0 = none. */
  lockIn?: number;
}

export type EffectDef =
  | { type: 'etaMul'; era: EraId; value: number }          // efficiency ×value
  | { type: 'capCostMul'; era: EraId; value: number }      // c ×value
  | { type: 'marginAdd'; era: EraId; value: number }       // m += value
  | { type: 'reserveAdd'; era: EraId; value: number }      // 'stock': Q += value * Q0 ; 'flow': capacity += value * reserve
  | { type: 'absorptionAdd'; era: EraId; value: number }   // absorption += value
  | { type: 'reveal' }                                     // sets flags.revealed (The Coal Question)
  | { type: 'startCapitalMul'; value: number }             // knowhow / institutions only
  | { type: 'mandateRateMul'; value: number }
  | { type: 'startLever'; lever: string; level: number }   // institution: lever starts each run at this level, free
  | { type: 'costMul'; value: number };                    // all upgrade capital costs ×value

export interface UpgradeDef {
  id: string;              // 'steam.condenser'
  era: EraId;
  name: string;            // "Separate condenser"
  blurb: string;           // "Watt, 1769. Stop cooling the cylinder."
  /** 'efficiency' cards show the promise line and the projected line. */
  kind: 'efficiency' | 'capital' | 'prospect' | 'research';
  /** Capital cost of the first purchase. */
  cost: number;
  /** For repeatable upgrades: cost of level n = cost * costGrowth^n. */
  repeatable?: boolean;
  costGrowth?: number;
  maxLevel?: number;
  /** Ids of upgrades that must be owned first. */
  requires?: string[];
  effects: EffectDef[];
}

export type LeverKind =
  /** Tax that holds the service price up as η rises. Per level, strength s (0–1):
   *  p_s' = p_s + s * max(0, p_ref - p_s), p_ref = p_s when first enacted. Tax revenue is not player income. */
  | 'duty'
  /** Hard ceiling on R = capFraction * (R when enacted). A permit price is added to p_r until R meets the cap.
   *  If the permit price exceeds `leakAbove` × p_r, a share of demand leaks around the cap. */
  | 'cap'
  /** Saturation of the era's applications drifts down toward `target` × S_i at `rate` per second. */
  | 'sufficiency'
  /** A share of the service is supplied from a renewable flow: uses no resource, makes no pressure,
   *  costs `capCostMul` more capital per unit, limited to `flowCap` units of service per second. */
  | 'substitution'
  /** A share of resource used returns to the reserve ('stock') . */
  | 'circularity'
  /** Cuts this era's indirect spill by a share. */
  | 'greenSpending'
  /** Era 5: spends a share of attention capacity to shrink P (the code stock) at `rate` per unit attention. */
  | 'deletion'
  /** Era 5: shipped service limited to reviewed service; removes the defect penalty, lowers D. */
  | 'reviewGate'
  /** Era 5: pressureIntensity × (1 - share). */
  | 'sharedLibs';

export interface LeverDef {
  id: string;              // 'steam.duty'
  era: EraId;
  kind: LeverKind;
  name: string;            // "Fuel duty escalator"
  blurb: string;
  /** What the catch is, in the UI's words. */
  catch: string;
  /** One entry per level (level 1 = index 0). Level 0 = off. */
  levels: LeverLevelDef[];
  /** Upgrade or flag gates. Levers are hidden until `flags.revealed` unless stated otherwise. */
  requires?: string[];
}

export interface LeverLevelDef {
  /** One-off Mandate to reach this level from the one below. */
  mandateCost: number;
  /** Mandate per second while held at this level. If Mandate hits 0 the lever drops one level. */
  mandateUpkeep: number;
  /** Meaning depends on kind: duty strength, capFraction, sufficiency target, substitution share,
   *  circularity share, greenSpending share, deletion share of capacity, reviewGate share, sharedLibs share. */
  value: number;
  /** Secondary knob: sufficiency rate, substitution flowCap, cap leakAbove, deletion rate. */
  value2?: number;
  /** Short label for the level button: "Hold price at 60%". */
  label: string;
}

/** Permanent, bought with Hindsight, the tempting kind: makes runs faster and shorter. */
export interface KnowhowDef {
  id: string;
  name: string;
  blurb: string;
  /** Hindsight cost of level n = cost * costGrowth^n. */
  cost: number;
  costGrowth: number;
  maxLevel: number;
  /** Applied once per level owned. */
  effects: EffectDef[];
}

/** Permanent, bought with Hindsight, the slow kind: counter-levers in place from the start. */
export interface InstitutionDef {
  id: string;
  name: string;
  blurb: string;
  cost: number;
  requires?: string[];     // other institution ids
  effects: EffectDef[];
}

export interface AchievementDef {
  id: 'jevonsWasRight' | 'degrowthByAccident' | 'steadyState' | 'firstReckoning' | 'backfire' | string;
  name: string;
  blurb: string;
  hidden?: boolean;
}

export type HeadlineKey =
  | 'appFounded' | 'appAvailable' | 'eraOpened' | 'crisis' | 'collapse' | 'exhausted'
  | 'backfire'        // first time an era's rebound passes 100%
  | 'reveal' | 'leverEnacted' | 'leverLapsed' | 'steadyEra' | 'steadyAll' | 'reckoning' | 'efficiency';

/* ------------------------------------------------------------------ */
/* STATE (serialisable, plain JSON)                                    */
/* ------------------------------------------------------------------ */

export interface GameState {
  version: number;
  seed: number;
  /** Seconds played this run. */
  time: number;
  capital: number;
  mandate: number;
  population: number;
  peakPopulation: number;
  /** Bought this run: upgrade id → level (1 for one-offs). */
  upgrades: Record<string, number>;
  /** lever id → state. */
  levers: Record<string, LeverState>;
  eras: Record<EraId, EraState>;
  flags: {
    /** The Coal Question has been researched (or the Statistics Office institution is owned). */
    revealed: boolean;
    /** Overall Steady State reached this run. */
    won: boolean;
  };
  /** Consecutive in-game years in which every open era has been decoupling. */
  steadyYearsAll: number;
  news: NewsItem[];        // newest first, capped at 40
  /** Sampled every `historyEvery` seconds, capped at 240 samples (older samples thinned). */
  history: HistorySample[];
  run: RunStats;
  /** Survives a Reckoning. */
  meta: MetaState;
}

export interface EraState {
  open: boolean;
  /** Seconds since this era opened (0 if closed). */
  openFor: number;
  /** Current efficiency including upgrades, knowhow and autoEta. */
  eta: number;
  /** 'stock': remaining reserve. 'flow': unused. */
  reserve: number;
  /** Total reserve ever available this run (Q0 + additions) — the denominator for the gauge and the price. */
  reserveMax: number;
  pressure: number;
  /** Indices of crisisAt thresholds already fired. */
  crisesFired: number;
  /** application id → state */
  apps: Record<string, AppState>;
  /** R and D at the moment the era opened: the baseline for the rebound meter and "Jevons Was Right". */
  baseR: number;
  baseD: number;
  /** p_s at the moment the era opened (for spill). */
  basePs: number;
  /** Slow moving averages for the trend arrow and decoupling test. */
  smoothR: number;
  /** d(smoothR)/dt as a fraction of smoothR per in-game year. Negative = falling. */
  trendR: number;
  peakR: number;
  /** Consecutive in-game years this era has been decoupling (trendR < 0 while wellbeing >= target). */
  steadyYears: number;
  backfired: boolean;
}

export interface AppState {
  available: boolean;
  founded: boolean;
  /** Current saturation multiplier from sufficiency levers (starts 1). */
  satMul: number;
  /** Highest demand reached (for lock-in). */
  peakD: number;
}

export interface LeverState {
  level: number;
  /** Snapshot taken when the lever first went from 0 to >0 (p_ref for duty, R for cap). */
  ref: number;
}

export interface NewsItem {
  time: number;
  year: number;
  key: HeadlineKey;
  text: string;
  era?: EraId;
}

export interface HistorySample {
  time: number;
  /** era id → [eta relative to baseEta, R relative to baseR]. Absent while the era is closed. */
  eras: Partial<Record<EraId, [number, number]>>;
  wellbeing: number;
}

export interface RunStats {
  peakWellbeing: number;
  /** Total in-game years any era spent decoupling this run. */
  decoupledYears: number;
  /** Sum of all resource used this run, per era. */
  resourceUsed: Partial<Record<EraId, number>>;
  clicks: number;
}

export interface MetaState {
  hindsight: number;
  hindsightEarned: number;
  reckonings: number;
  knowhow: Record<string, number>;
  institutions: Record<string, boolean>;
  achievements: Record<string, boolean>;
  /** Eras that have reached per-era Steady State at least once. */
  steadyEras: Partial<Record<EraId, boolean>>;
  /** Furthest era index ever opened. */
  furthestEra: number;
  /** Summary of the previous run for the Reckoning card. */
  lastRun?: RunSummary;
  totalSeconds: number;
}

export interface RunSummary {
  cause: ReckoningCause;
  causeEra?: EraId;
  seconds: number;
  yearReached: number;
  hindsightGained: number;
  peakWellbeing: number;
  /** Per era open at the end: how much more efficient, how much more resource per second at peak. */
  eras: Partial<Record<EraId, { etaFold: number; peakRFold: number; resourceUsed: number }>>;
}

export type ReckoningCause = 'exhausted' | 'collapse' | 'chosen';

/* ------------------------------------------------------------------ */
/* DERIVED (recomputed from state every frame, never stored)           */
/* ------------------------------------------------------------------ */

export interface Derived {
  year: number;
  wellbeing: number;                // 0–100-ish
  incomePerSec: number;
  mandatePerSec: number;            // net of lever upkeep
  populationGrowthPerSec: number;
  /** A forced Reckoning is pending (model.tick stops advancing; UI must show the Reckoning screen). */
  pendingReckoning: { cause: ReckoningCause; era?: EraId } | null;
  hindsightIfReckonNow: number;
  eras: Partial<Record<EraId, EraDerived>>;   // open eras only
  /** Next closed era and how close it is to opening, or null if all open. */
  nextEra: { id: EraId; priceNow: number; priceNeeded: number; reckoningsNeeded: number; reckoningsHave: number } | null;
}

export interface EraDerived {
  eta: number;
  etaFold: number;                  // eta / baseEta
  resourcePrice: number;            // p_r incl. permits
  servicePrice: number;             // p_s the customer pays (incl. duty)
  demand: number;                   // D, service per second
  resourceUse: number;              // R per second
  rFold: number;                    // R / baseR
  /** What R would be had demand stayed at baseD: baseR / etaFold. "Promised on the cards." */
  promisedR: number;
  /** Share of promised savings eaten by extra demand; > 1 is backfire. null until η has changed. */
  rebound: number | null;
  income: number;
  /** 'stock': reserve / reserveMax. 'flow': 1 - utilisation. */
  reserveFraction: number;
  /** Seconds until exhaustion at the current rate ('stock'), Infinity otherwise. */
  secondsLeft: number;
  pressureFraction: number;         // P / collapseAt
  trendR: number;
  decoupling: boolean;
  steadyYears: number;
  wellbeingShare: number;           // this era's contribution to wellbeing
  apps: Record<string, AppDerived>;
}

export interface AppDerived {
  available: boolean;
  founded: boolean;
  demand: number;
  /** demand / current saturation, 0–1. */
  adoption: number;
  canFound: boolean;
}

export interface UpgradeView {
  def: UpgradeDef;
  level: number;
  /** Capital cost of the next purchase (after cost multipliers). */
  cost: number;
  visible: boolean;                 // era open and prerequisites met
  affordable: boolean;
  maxed: boolean;
  /** Efficiency cards: the engineer's promise, e.g. -0.6 for "−60% coal per unit of power". */
  promisedChange: number | null;
  /** Efficiency cards, after the reveal: projected change in the era's total R, e.g. +0.24. */
  projectedChange: number | null;
}

export interface LeverView {
  def: LeverDef;
  level: number;
  visible: boolean;
  /** Mandate needed for the next level, null if at max. */
  nextCost: number | null;
  canRaise: boolean;
  upkeep: number;
}

/* ------------------------------------------------------------------ */
/* MODEL API                                                           */
/* ------------------------------------------------------------------ */

export interface ModelApi {
  /** Fresh run. Pass the previous meta to carry Hindsight, knowhow and institutions over. */
  createState(content: Content, meta?: MetaState, seed?: number): GameState;

  /** Advance by dt seconds (dt ≤ 1 is stepped as given; larger dt is sub-stepped internally). */
  tick(state: GameState, content: Content, dt: number): GameState;
  /** Offline catch-up: coarse steps, capped at content.global.offlineCapSeconds, stops at a pending Reckoning. */
  fastForward(state: GameState, content: Content, seconds: number): GameState;

  derive(state: GameState, content: Content): Derived;

  /* --- player actions: each returns the new state, or the same reference if the action is not allowed --- */
  click(state: GameState, content: Content): GameState;
  buyUpgrade(state: GameState, content: Content, upgradeId: string): GameState;
  foundApp(state: GameState, content: Content, appId: string): GameState;
  /** Raise or lower a lever to `level`. Raising charges Mandate; lowering is free and immediate. */
  setLever(state: GameState, content: Content, leverId: string, level: number): GameState;
  /** End the run. Uses the pending cause if there is one, else 'chosen'. Returns the fresh next run. */
  reckon(state: GameState, content: Content): GameState;
  buyKnowhow(state: GameState, content: Content, id: string): GameState;
  buyInstitution(state: GameState, content: Content, id: string): GameState;

  /* --- views for the UI --- */
  upgradeViews(state: GameState, content: Content): UpgradeView[];
  leverViews(state: GameState, content: Content): LeverView[];
  hindsightOnReckon(state: GameState, content: Content): number;

  /* --- persistence --- */
  serialize(state: GameState): string;
  /** Returns null if the string is not a usable save. Must tolerate saves missing newer fields. */
  deserialize(text: string, content: Content): GameState | null;
}
